using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
public static class FixHud06BFontOwnership {public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var s=h.Sandbox.RailwayHud.GetComponent<RailwayOverview>().Services;var indices=Enumerable.Range(0,h.Layout.Texts.Length).Where(i=>h.Layout.Texts[i]==null||!h.Layout.Texts[i].transform.IsChildOf(s.Root)).ToArray();var sizes=indices.Select(i=>h.Layout.FontSizes[i]).ToArray();h.Layout.Texts=indices.Select(i=>h.Layout.Texts[i]).ToArray();h.Layout.FontSizes=sizes;EditorUtility.SetDirty(h.Layout);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Service inputs use physical 18px without legacy text rescaling";}}
